using SASZombieAssaultTD.Engine.Rendering;using SASZombieAssaultTD.Engine.Diagnostics;  using SASZombieAssaultTD.Engine.Rendering;  // Resolve IRenderContext ambiguity using IRenderContext = SASZombieAssaultTD.Engine.Rendering.IRenderContext;  namespace SASZombieAssaultTD.Engine.UI {     /// <summary>     /// Cash HUD panel renderer implementing IHUDElement interface.     /// Renders the cash display panel with background fill and text.     /// Receives colors exclusively from HUDPanel_Finalizer through HUDManager.     /// No baked-in defaults, flash colors, or fallback logic are applied.     /// All colors are determined by the Finalizer's color pipeline authority.     /// </summary>     public class HUDPanel_Cash : IHUDElement     {         /// <summary>         /// Unique identifier for this HUD panel element.         /// Used by HUDManager for element tracking and render order management.         /// Matches the panel identifier used in HUDPanel_Finalizer configuration.         /// </summary>         public string Id => "cash_panel";          /// <summary>         /// Reference to the HUDManager instance that owns this panel.         /// Used for accessing shared resources like the texture manager.         /// May be null if panel is created without HUDManager injection.         /// </summary>         private readonly HUDManager _hudManager;          // ---------------------------------------------------------         // PANEL GEOMETRY (POSITION AND SIZE)         // ---------------------------------------------------------          /// <summary>         /// Horizontal position of the cash panel in screen coordinates.         /// Determines the left edge of the panel background rectangle.         /// Values are set by HUDManager during initialization from Finalizer config.         /// </summary>         public int X { get; set; } = 100;          /// <summary>         /// Vertical position of the cash panel in screen coordinates.         /// Determines the top edge of the panel background rectangle.         /// Values are set by HUDManager during initialization from Finalizer config.         /// </summary>         public int Y { get; set; } = 540;          /// <summary>         /// Width of the cash panel background in pixels.         /// Determines the size of the fill rectangle.         /// Values are set by HUDManager during initialization from Finalizer config.         /// </summary>         public int Width { get; set; } = 75;          /// <summary>         /// Height of the cash panel background in pixels.         /// Determines the size of the fill rectangle.         /// Values are set by HUDManager during initialization from Finalizer config.         /// </summary>         public int Height { get; set; } = 22;          // ---------------------------------------------------------         // DEFAULT COLORS (USED WHEN MANUAL OVERRIDE DISABLED)         // ---------------------------------------------------------          /// <summary>         /// Default background color used when manual override is disabled.         /// Semi-transparent dark gray (0.18, 0.18, 0.18, 0.85).         /// Applied only when UseManualColors is false.         /// No flash colors or fallbacks are used.         /// </summary>         private readonly Color _defaultBackgroundColor = Color.FromArgb(0.18f, 0.18f, 0.18f, 0.85f);          /// <summary>         /// Default text color used when manual override is disabled.         /// Solid white for maximum contrast against dark background.         /// Applied only when UseManualColors is false.         /// No flash colors or fallbacks are used.         /// </summary>         private readonly Color _fallbackTextColor = Color.White;          // ---------------------------------------------------------         // RENDERING RESOURCES         // ---------------------------------------------------------          /// <summary>         /// White pixel texture used for drawing the panel background.         /// Loaded lazily from texture manager during first Draw call.         /// Tinted with background color to create colored rectangles.         /// </summary>         private Texture2D _whitePixel;          /// <summary>         /// Text content displayed in the cash panel.         /// Updated by HUDPanel_Finalizer during color distribution.         /// Default value is "$0" before initialization.         /// </summary>         internal string DisplayText { get; set; } = "$0";          /// <summary>         /// Rendering layer priority for this HUD element.         /// Higher values render on top of lower values.         /// Set to 998 to ensure proper z-ordering in HUD render pipeline.         /// </summary>         public int Layer => 998;          // ---------------------------------------------------------         // FINALIZER COLOR PROPERTIES (RECEIVED FROM HUDMANAGER)         // ---------------------------------------------------------          /// <summary>         /// Manual fill color received from Finalizer through HUDManager.         /// Used exclusively when UseManualColors is true.         /// No defaults, fallbacks, or flash colors are applied.         /// </summary>         internal Color ManualFillColor { get; set; }          /// <summary>         /// Manual text color received from Finalizer through HUDManager.         /// Used exclusively when UseManualColors is true.         /// No defaults, fallbacks, or flash colors are applied.         /// </summary>         internal Color ManualTextColor { get; set; }          /// <summary>         /// Indicates whether manual colors from Finalizer should be used.         /// Set by HUDManager during Finalizer color distribution.         /// </summary>         internal bool UseManualColors { get; set; } = false;          // ---------------------------------------------------------         // CONSTRUCTORS         // ---------------------------------------------------------          /// <summary>         /// Default constructor for HUDPanel_Cash.         /// Creates panel without HUDManager reference.         /// Used when panel is instantiated without dependency injection.         /// _hudManager remains null, limiting some functionality.         /// </summary>         public HUDPanel_Cash()         { }          /// <summary>         /// Constructor with HUDManager dependency injection.         /// Creates panel with reference to owning HUDManager.         /// Enables access to shared resources like texture manager.         /// Preferred constructor for proper integration with HUD system.         /// </summary>         /// <param name="hudManager">Reference to the owning HUDManager instance</param>         public HUDPanel_Cash(HUDManager hudManager)         {             _hudManager = hudManager;         }          // ---------------------------------------------------------         // UPDATE METHOD (IHUDElement IMPLEMENTATION)         // ---------------------------------------------------------          /// <summary>         /// Required IHUDElement Update method.         /// Cash panel has no runtime update logic by design.         /// All rendering state is determined during Draw call.         /// Called once per frame by HUDManager before Draw.         /// </summary>         /// <param name="deltaTime">Time elapsed since last frame in seconds</param>         public void Update(float deltaTime)         {             System.Diagnostics.Debug.WriteLine("[DIAG] HUDPanel_Cash.Update - STUB PROCESSED");         }          // ---------------------------------------------------------         // DRAW METHOD (IHUDElement IMPLEMENTATION)         // ---------------------------------------------------------          /// <summary>         /// Renders the cash panel background and text.         /// Required IHUDElement Draw method called once per frame.         /// Draws white pixel rectangle tinted with background color.         /// Renders DisplayText using monospaced digit font.         /// Uses Finalizer colors exclusively when UseManualColors is true.         /// Falls back to default colors only when manual override disabled.         /// No flash colors or runtime color modifications are applied.         /// </summary>         /// <param name="context">Render context provided by HUD system</param>         public void Draw(IRenderContext context)         {             if (context is not Framebuffer fb)                 return;              // Load white pixel             if (_whitePixel == null && HUDManager.Instance != null)             {                 var textureManager = HUDManager.Instance.GetType()                     .GetField("_textureManager", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)?                     .GetValue(HUDManager.Instance) as TextureManager;                  if (textureManager != null)                     _whitePixel = textureManager.Get("Assets/UI/white_pixel.png");             }              if (_whitePixel == null)                 return;              // ---------------------------------------------------------             // BACKGROUND COLOR (FINALIZER COLORS ONLY)             // ---------------------------------------------------------             System.Diagnostics.Debug.WriteLine("=== DIAGNOSTIC: HUDPanel_Cash Draw - BACKGROUND COLOR ===");             System.Diagnostics.Debug.WriteLine($"[CASH PANEL] UseManualColors: {UseManualColors}");             System.Diagnostics.Debug.WriteLine($"[CASH PANEL] ManualFillColor: ({ManualFillColor.R:F3},{ManualFillColor.G:F3},{ManualFillColor.B:F3},{ManualFillColor.A:F3})");             System.Diagnostics.Debug.WriteLine($"[CASH PANEL] DefaultBackgroundColor: ({_defaultBackgroundColor.R:F3},{_defaultBackgroundColor.G:F3},{_defaultBackgroundColor.B:F3},{_defaultBackgroundColor.A:F3})");              Color backgroundColor;              if (UseManualColors)             {                 // Use Finalizer fill color exclusively                 backgroundColor = ManualFillColor;                 System.Diagnostics.Debug.WriteLine($"[CASH PANEL] Using Finalizer fill color: ({ManualFillColor.R:F3},{ManualFillColor.G:F3},{ManualFillColor.B:F3},{ManualFillColor.A:F3})");             }             else             {                 // No fallback colors - use default when manual override disabled                 backgroundColor = _defaultBackgroundColor;                 System.Diagnostics.Debug.WriteLine($"[CASH PANEL] Manual override disabled, using default background: ({_defaultBackgroundColor.R:F3},{_defaultBackgroundColor.G:F3},{_defaultBackgroundColor.B:F3},{_defaultBackgroundColor.A:F3})");             }              System.Diagnostics.Debug.WriteLine($"[CASH PANEL] Drawing background with color: ({backgroundColor.R:F3},{backgroundColor.G:F3},{backgroundColor.B:F3},{backgroundColor.A:F3})");             fb.DrawTexture(_whitePixel, X, Y, Width, Height);              // ---------------------------------------------------------             // TEXT COLOR (FINALIZER COLORS ONLY)             // ---------------------------------------------------------             System.Diagnostics.Debug.WriteLine("=== DIAGNOSTIC: HUDPanel_Cash Draw - TEXT COLOR ===");             System.Diagnostics.Debug.WriteLine($"[CASH PANEL] UseManualColors: {UseManualColors}");             System.Diagnostics.Debug.WriteLine($"[CASH PANEL] ManualTextColor: ({ManualTextColor.R:F3},{ManualTextColor.G:F3},{ManualTextColor.B:F3},{ManualTextColor.A:F3})");             System.Diagnostics.Debug.WriteLine($"[CASH PANEL] FallbackTextColor: ({_fallbackTextColor.R:F3},{_fallbackTextColor.G:F3},{_fallbackTextColor.B:F3},{_fallbackTextColor.A:F3})");              Color textColor;              if (UseManualColors)             {                 // Use Finalizer text color exclusively                 textColor = ManualTextColor;                 System.Diagnostics.Debug.WriteLine($"[CASH PANEL] Using Finalizer text color: ({ManualTextColor.R:F3},{ManualTextColor.G:F3},{ManualTextColor.B:F3},{ManualTextColor.A:F3})");             }             else             {                 // No fallback colors - use default when manual override disabled                 textColor = _fallbackTextColor;                 System.Diagnostics.Debug.WriteLine($"[CASH PANEL] Manual override disabled, using default text color");             }              float textX = X + 4f;             float textY = Y + 4f;              context.DrawMonospacedDigits(DisplayText, textX, textY, textColor, 14f);              // ---------------------------------------------------------             // OPTIONAL PLUS SIGN (FINALIZER COLORS ONLY)             // ---------------------------------------------------------             if (UseManualColors)             {                 // Use Finalizer text color for plus sign                 var plusColor = ManualTextColor;                  float plusX = X + Width - 14f;                 float plusY = Y + 4f;                  // context.DrawText("+", plusX, plusY, plusColor, 16f);                 System.Diagnostics.Debug.WriteLine($"[CASH PANEL] Plus sign would use Finalizer color: ({plusColor.R:F3},{plusColor.G:F3},{plusColor.B:F3},{plusColor.A:F3})");             }             else             {                 System.Diagnostics.Debug.WriteLine($"[CASH PANEL] Manual override disabled, plus sign not rendered");             }         }     } }
